INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT134-S1-Q6$batch04$, 134, 1, 6, $batch04$Paradox$batch04$, $batch04$The number of tornadoes recorded annually in North America has more than tripled since 1953. Yet meteorologists insist that the climatic factors affecting the creation of tornadoes are unchanged.$batch04$, $batch04$Which one of the following, if true, most helps to resolve the apparent discrepancy described above?$batch04$, $batch04$E$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=134 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT134-S1-Q6$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$The factors affecting the creation of tornadoes were not well known to meteorologists before 1953.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT134-S1-Q6$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$The intensity of the average tornado is greater now than it was in 1953.$batch04$, $batch04$Deepens Paradox$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT134-S1-Q6$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$The number of tornadoes recorded annually has increased only slightly in the last five years.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT134-S1-Q6$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$The amount of property damage done by tornadoes has grown substantially since 1953.$batch04$, $batch04$Out of Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT134-S1-Q6$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$Many more citizens are helping authorities detect tornadoes now than in 1953.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT134-S1-Q6$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT134-S1-Q6$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$The climate factors that create tornadoes have not changed since 1953.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$The number of tornadoes *recorded* each year has more than tripled?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Look at the word "recorded." The number of tornadoes could stay the same while the number we notice and write down goes up. Better detection would resolve it.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a reason more tornadoes are recorded without more tornadoes happening.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT134-S1-Q6$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Meteorologists understanding the factors better now does not change how many tornadoes are recorded.$batch04$), ($batch04$B$batch04$, $batch04$Stronger tornadoes suggest something about the climate has changed, which makes the meteorologists' claim harder to believe.$batch04$), ($batch04$C$batch04$, $batch04$A slow rise in the last five years does not explain the tripling since 1953.$batch04$), ($batch04$D$batch04$, $batch04$Property damage depends on how much property is in the way. It does not explain more recorded tornadoes.$batch04$), ($batch04$E$batch04$, $batch04$Many more citizens now help detect tornadoes. More tornadoes get noticed and recorded, while the number actually forming stays the same.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT134-S1-Q6$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
